<?php
namespace App\Http\Controllers; use App\Domain\Catalog\Models\Product; use App\Domain\Commerce\Models\Order; use App\Domain\Inventory\Models\Inventory; use App\Domain\Returns\Models\ReturnRequest; use Inertia\Inertia; class AdminDashboardController {public function __invoke(){return Inertia::render('Admin/Dashboard',['metrics'=>['products'=>Product::count(),'orders'=>Order::count(),'lowStock'=>Inventory::whereRaw('(quantity_on_hand - quantity_reserved) <= 5')->count(),'openReturns'=>ReturnRequest::whereNotIn('status',['completed','rejected','cancelled'])->count()],'recentOrders'=>Order::latest('placed_at')->limit(6)->get(['order_number','customer_email','total_amount','currency','payment_status','fulfillment_status','placed_at'])]);}}